package com.learnagent.memory;

import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="flashcard_review_states")public class FlashcardReviewState{@Id@Column(name="card_id")private UUID cardId;@Column(name="fsrs_card_json",nullable=false,columnDefinition="text")private String fsrsCardJson;private Double difficulty;private Double stability;@Column(nullable=false)private double retrievability;@Column(name="due_at",nullable=false)private Instant dueAt;@Column(name="last_review_at")private Instant lastReviewAt;@Column(name="review_count",nullable=false)private int reviewCount;@Column(name="lapse_count",nullable=false)private int lapseCount;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected FlashcardReviewState(){}public FlashcardReviewState(UUID cardId,String cardJson,Instant due){this.cardId=cardId;fsrsCardJson=cardJson;dueAt=due;retrievability=1;updatedAt=Instant.now();}public void update(String cardJson,Double difficulty,Double stability,double retrievability,Instant due,Instant reviewed,boolean lapse){fsrsCardJson=cardJson;this.difficulty=difficulty;this.stability=stability;this.retrievability=retrievability;dueAt=due;lastReviewAt=reviewed;reviewCount++;if(lapse)lapseCount++;updatedAt=Instant.now();}public void refreshRetrievability(double value){retrievability=value;updatedAt=Instant.now();}public UUID getCardId(){return cardId;}public String getFsrsCardJson(){return fsrsCardJson;}public Double getDifficulty(){return difficulty;}public Double getStability(){return stability;}public double getRetrievability(){return retrievability;}public Instant getDueAt(){return dueAt;}public Instant getLastReviewAt(){return lastReviewAt;}public int getReviewCount(){return reviewCount;}public int getLapseCount(){return lapseCount;}}
